// Extract Udarsy's ranking from SERP results
const item = $input.first().json;
const keyword = $('Define Keywords').first().json.keyword;
const language = $('Define Keywords').first().json.language;

const organicResults = item.organic_results || [];
const udarsyDomains = ['udarsy.io', 'udarsy.dz', 'udarsy.com', 'www.udarsy.io'];

let udarsyPosition = -1;
let udarsyUrl = '';
let udarsyTitle = '';

for (let i = 0; i < organicResults.length; i++) {
  const result = organicResults[i];
  const link = (result.link || '').toLowerCase();
  if (udarsyDomains.some(domain => link.includes(domain))) {
    udarsyPosition = result.position || (i + 1);
    udarsyUrl = result.link;
    udarsyTitle = result.title;
    break;
  }
}

// Top 3 competitors for this keyword
const topCompetitors = organicResults.slice(0, 5).map(r => ({
  position: r.position,
  title: r.title,
  domain: (r.link || '').replace(/https?:\/\/([^/]+).*/, '$1')
}));

return [{
  json: {
    keyword,
    language,
    udarsy_position: udarsyPosition,
    udarsy_url: udarsyUrl,
    udarsy_title: udarsyTitle,
    in_top_10: udarsyPosition > 0 && udarsyPosition <= 10,
    in_top_20: udarsyPosition > 0 && udarsyPosition <= 20,
    not_found: udarsyPosition === -1,
    top_competitors: JSON.stringify(topCompetitors),
    total_results: item.search_information?.total_results || 0,
    checked_at: new Date().toISOString()
  }
}];

// Compare current rankings with previous day
const currentItems = $('Extract Udarsy Ranking').all();
const previousRows = $('Read Previous Rankings').all();

// Build a map of previous rankings (latest entry per keyword)
const prevMap = {};
previousRows.forEach(row => {
  const kw = row.json.keyword;
  if (!prevMap[kw] || new Date(row.json.checked_at) > new Date(prevMap[kw].checked_at)) {
    prevMap[kw] = row.json;
  }
});

const results = currentItems.map(item => {
  const curr = item.json;
  const prev = prevMap[curr.keyword];
  const prevPosition = prev ? parseInt(prev.udarsy_position) : -1;
  const currPosition = curr.udarsy_position;

  let change = 'no_change';
  let positionDelta = 0;
  let significant = false;

  if (prevPosition === -1 && currPosition > 0) {
    change = 'new_entry';
    significant = true;
  } else if (prevPosition > 0 && currPosition === -1) {
    change = 'dropped_out';
    significant = true;
  } else if (prevPosition > 0 && currPosition > 0) {
    positionDelta = prevPosition - currPosition; // positive = improved
    if (positionDelta > 0) change = 'improved';
    else if (positionDelta < 0) change = 'declined';
    significant = Math.abs(positionDelta) >= 3;
  }

  return {
    json: {
      ...curr,
      previous_position: prevPosition,
      position_delta: positionDelta,
      change,
      significant
    }
  };
});

return results;

