// Check if any significant changes warrant a Telegram alert
const items = $('Compare Rankings').all();
const analysis = $input.first().json;

const significantChanges = items.filter(i => i.json.significant);
const hasSignificantChanges = significantChanges.length > 0;

// Parse AI analysis
let aiReport;
try {
  const text = analysis.message?.content || analysis.text || JSON.stringify(analysis);
  const jsonMatch = text.match(/```json\n?([\s\S]*?)\n?```/) || text.match(/\{[\s\S]*\}/);
  aiReport = JSON.parse(jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : text);
} catch (e) {
  aiReport = { summary: 'Failed to parse AI analysis', error: e.message };
}

// Build Telegram message
let msg = `📊 *Udarsy SEO Daily Report*\n\n`;
msg += `📈 *Summary:* ${aiReport.summary || 'N/A'}\n`;
msg += `📉 *Trend:* ${aiReport.overall_trend || 'N/A'}\n\n`;

if (significantChanges.length > 0) {
  msg += `⚠️ *Significant Changes:*\n`;
  significantChanges.forEach(c => {
    const d = c.json;
    const arrow = d.position_delta > 0 ? '⬆️' : '⬇️';
    msg += `  ${arrow} "${d.keyword}": ${d.previous_position} → ${d.udarsy_position} (${d.change})\n`;
  });
  msg += '\n';
}

if (aiReport.priority_actions?.length > 0) {
  msg += `🎯 *Priority Actions:*\n`;
  aiReport.priority_actions.forEach((a, i) => {
    msg += `  ${i + 1}. ${a}\n`;
  });
}

return [{ json: { message: msg, send_alert: hasSignificantChanges, report: aiReport } }];

// Gets chatId from Telegram command center webhook, or falls back to env var
const fromWebhook = $input.first().json.body?.chatId;
const chatId = fromWebhook || $env.TELEGRAM_CHAT_ID;
return [{ json: { chatId } }];
